    /// <summary>
    /// The decisions that turn a parser expression into something that runs: what the lazy parsers resolve to,
    /// and which parsers are wrapped (memoization, growing, stack guards) or bypassed.
    /// Both the parser implementations and the generated source follow the same plan, so they parse alike.
    /// </summary>
    internal sealed class ParserPlan
    {
        private readonly List<IParser> parsers;
        private readonly Dictionary<ILazyParser, IParser> lazyTargets;
        private readonly List<Step> steps;

        private ParserPlan(List<IParser> parsers, Dictionary<ILazyParser, IParser> lazyTargets, List<Step> steps)
        {
            this.parsers = parsers;
            this.lazyTargets = lazyTargets;
            this.steps = steps;
        }

        /// <summary>
        /// Gets the parsers that need a node of their own, which are all parsers except the lazy ones.
        /// </summary>
        public IReadOnlyList<IParser> Parsers => parsers;

        /// <summary>
        /// Creates the plan for the parsers found by <paramref name="analysis"/>.
        /// </summary>
        /// <param name="analysis">The analysis of the root parser.</param>
        /// <param name="options">The simplified parse options.</param>
        /// <returns>The plan.</returns>
#pragma warning disable S3776 // Cognitive Complexity of methods should not be too high
        public static ParserPlan Create(IReadOnlyParserAnalysisInfo analysis, ParseOptions options)
#pragma warning restore S3776 // Cognitive Complexity of methods should not be too high
        {
            var all = analysis.OccurrenceCounts.Keys.ToList();
            var lazyTargets = ResolveLazyParsers(all);
            var steps = new List<Step>();

            LeftRecursionInfo? leftRecursion = null;

            if (options.EnableAutomaticGrowingRecursion)
            {
                leftRecursion = LeftRecursionAnalysis.Analyze(all, new HashSet<IParser>(lazyTargets.Values));
            }

            if (options.EnableAutomaticMemoization)
            {
                // Only memoize where backtracking can run a parser again at the same position.
                var requiresMemo = new HashSet<IParser>(LeftRecursionAnalysis.FindRetried(all)
                    .Select(p => p is ILazyParser lp ? lazyTargets[lp] : p));

                // Members of a left-recursive cycle must not be memoized, or they keep returning results built from an outdated seed.
                if (leftRecursion is not null)
                {
                    requiresMemo.ExceptWith(leftRecursion.Members);
                }

                // Explicit memo and grow parsers already memoize. Wrapping a grow parser would hide its growing seed.
                // Cheap parsers are faster to run again than to look up.
                requiresMemo.RemoveWhere(p => LeftRecursionAnalysis.IsGrow(p) || LeftRecursionAnalysis.IsMemo(p) || LeftRecursionAnalysis.IsCheap(p));

                foreach (var parser in requiresMemo)
                {
                    steps.Add(Step.Wrap(typeof(MemoParser<>), parser));
                }
            }

            if (leftRecursion is not null)
            {
                foreach (var parser in leftRecursion.Leaders)
                {
                    steps.Add(Step.Wrap(typeof(GrowParser<>), parser));
                }

                foreach (var group in leftRecursion.LeaderlessGroups)
                {
                    var key = new CycleGrowGroup();
                    foreach (var parser in group)
                    {
                        steps.Add(Step.Wrap(typeof(CycleGrowParser<>), parser, key));
                    }
                }

                // Bypass explicit memo parsers inside a left-recursive cycle, for the same reason as above.
                foreach (var memo in leftRecursion.Members.OfType<IMemoParser>())
                {
                    steps.Add(Step.Alias(memo, SkipBypassed(memo.Parser, leftRecursion.Members, lazyTargets)));
                }
            }

            // Every cycle of the grammar passes through a parser that the analysis found recursively.
            // Guarding those bounds the stack used between two checks, so recursive mode throws
            // an InsufficientExecutionStackException instead of overflowing the stack.
            if (options.ExecutionMode != ParserExecutionMode.Iterative)
            {
                var guarded = new HashSet<IParser>();
                foreach (var parser in analysis.RecursiveOccurrenceCounts.Keys)
                {
                    var target = parser is ILazyParser lp ? lazyTargets[lp] : parser;
                    if (guarded.Add(target))
                    {
                        steps.Add(Step.Wrap(typeof(StackGuardParser<>), target));
                    }
                }
            }

            return new(all.Where(p => p is not ILazyParser).ToList(), lazyTargets, steps);
        }

        /// <summary>
        /// Builds the lookup table of the plan: every parser of the expression mapped to the node that runs it.
        /// </summary>
        /// <typeparam name="TNode">The type of the nodes.</typeparam>
        /// <param name="create">Creates the node of a parser in <see cref="Parsers"/>.</param>
        /// <param name="wrap">Creates the node of a wrapper parser, given the parser it wraps and the node that ran it so far.</param>
        /// <returns>The lookup table.</returns>
        public Dictionary<IParser, TNode> Execute<TNode>(Func<IParser, TNode> create, Func<IParser, IParser, TNode, TNode> wrap)
        {
            var lookup = new Dictionary<IParser, TNode>();

            foreach (var parser in parsers)
            {
                lookup[parser] = create(parser);
            }

            foreach (var step in steps)
            {
                lookup[step.Parser] = step.Wrapper is { } wrapper
                    ? wrap(wrapper, step.Parser, lookup[step.Parser])
                    : lookup[step.Target!];
            }

            foreach (var entry in lazyTargets)
            {
                lookup[entry.Key] = lookup[entry.Value];
            }

            return lookup;
        }

        private static Dictionary<ILazyParser, IParser> ResolveLazyParsers(List<IParser> all)
        {
            var lazyTargets = new Dictionary<ILazyParser, IParser>();

            foreach (var parser in all.OfType<ILazyParser>())
            {
                IParser target = parser;
                var seen = new HashSet<IParser>();

                while (target is ILazyParser lazyTarget)
                {
                    if (!seen.Add(lazyTarget))
                    {
                        throw new ArgumentException("Provided parser contains unsolvable recursive lazy parsers.");
                    }

                    target = lazyTarget.Parser.Value;
                }

                lazyTargets[parser] = target;
            }

            return lazyTargets;
        }

        private static IParser SkipBypassed(IParser parser, HashSet<IParser> bypassedMemos, Dictionary<ILazyParser, IParser> lazyTargets)
        {
            while (true)
            {
                if (parser is ILazyParser lazy)
                {
                    parser = lazyTargets[lazy];
                }
                else if (parser is IMemoParser memo && bypassedMemos.Contains(parser))
                {
                    parser = memo.Parser;
                }
                else
                {
                    return parser;
                }
            }
        }

        /// <summary>
        /// One change to the lookup table: either wrap a parser, or make it run another parser's node.
        /// </summary>
        private readonly struct Step
        {
            private Step(IParser parser, IParser? wrapper, IParser? target)
            {
                Parser = parser;
                Wrapper = wrapper;
                Target = target;
            }

            public IParser Parser { get; }

            public IParser? Wrapper { get; }

            public IParser? Target { get; }

            public static Step Wrap(Type wrapper, IParser parser, params object[] arguments)
            {
                var type = wrapper.MakeGenericType(parser.ResultType);
                return new(parser, (IParser)Activator.CreateInstance(type, [parser, .. arguments])!, null);
            }

            public static Step Alias(IParser parser, IParser target)
                => new(parser, null, target);
        }
    }
